info.description:
/* === FULL CHESS.COM BOARD OVERRIDE === */

/* Target ALL possible board containers */
[class*="board"], [class*="Board"] {
    background-image: none !important;
}

/* Light squares */
[class*="board"] [class*="light"],
[class*="Board"] [class*="light"] {
    background-color: #f5c542 !important;
    box-shadow: inset 0 0 8px rgba(255, 215, 0, 0.6) !important;
}

/* Dark squares */
[class*="board"] [class*="dark"],
[class*="Board"] [class*="dark"] {
    background-color: #8b0000 !important;
    box-shadow: inset 0 0 10px rgba(255, 0, 0, 0.7) !important;
}

/* Squares (general fallback) */
[class*="square"] {
    transition: all 0.2s ease-in-out !important;
}

